import{z as i,x as s,o as r,c as d,q as o,j as B,D as e,d as t,s as n,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"全球宏观","description":"","frontmatter":{"title":"全球宏观","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/global-macro.md","filePath":"quant/global-macro.md","lastUpdated":1791063341000}'),p={name:"quant/global-macro.md"};function D(m,a,u,h,f,F){const l=s("Mermaid");return r(),d("div",null,[a[2]||(a[2]=o('<h1 id="全球宏观" tabindex="-1">全球宏观 <a class="header-anchor" href="#全球宏观" aria-label="Permalink to &quot;全球宏观&quot;">​</a></h1><div class="epigraph"><p>全球宏观交易的是政策与周期在资产类别之间的相对价格；杠杆用在流动性好的期货上，辨识风险在叙事而不是在借券。</p><footer>—— 对照 Soros 的反身性叙述与机构宏观的风险预算实务；不是单一论文定义</footer></div><p><a href="/quant/event-driven-overview">上一课</a>的催化剂是公司事件。全球宏观的缺口是<strong>主权与政策时钟</strong>：利率、汇率、商品、股指的方向与相对价值。主干 <a href="/quant/bond-trend">债券趋势</a>、<a href="/quant/fx-carry-mom">外汇套息</a> 已写可系统化的腿。本课给策略族位置：宏观可以系统（趋势/套息）也可以相机，共同的是跨资产杠杆与叙事风险。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把宏观当「看对央行就能赚钱」，忽略：定价已经含预期、错误来自时机与仓位规模。系统宏观把趋势、套息、价值写成规则，IR 可检验；相机宏观把同一工具交给主观，评价要用后课业绩持续性，而不是用某一个十年的故事。问题是风险：宏观的亏损来自杠杆与相关（2013 taper、2022 股债双杀），不是来自单名挤仓。预算应用跨资产因子（久期、美元、油）而不是股票行业。</p><p>与相对价值宏观（后课固收 RV）：宏观常有净方向；RV 尽量对冲方向只留利差。两者在同一基金里常混，报告必须拆开。</p><h3 id="流动性好不等于风险小" tabindex="-1">流动性好不等于风险小 <a class="header-anchor" href="#流动性好不等于风险小" aria-label="Permalink to &quot;流动性好不等于风险小&quot;">​</a></h3><p>期货让宏观能迅速加到很大名义。冲击小，但缺口与保证金连环大，见 <a href="/quant/futures-margin">期货保证金</a>。容量公式与股票多空不同：先满的是保证金与监管头寸限额，不是借券。</p><p><span class="marginnote">宏观叙事容易事后拟合。研究日志课要求事先写出政策函数；本课只要求策略地图上把「系统」与「相机」分开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具：全球股指、国债、FX、商品期货。系统：趋势 + 套息 + 可选价值，波动瞄准。相机：明确的情景与失效条件。对冲：跨资产相关突变用情景，不用历史 \\(\\Sigma\\) 的 99%。与股票多空的相关要进总基金预算。</p><p><span class="marginnote">系统宏观就是用规则替人做决定的手段来做跨资产方向的事：信号、仓位、止损全写在代码里。相机宏观则是同一个判断交给人脑，交易的是「叙事」——所以业绩评价更难，一次押对不等于规则可复制。</span></p><p>一笔系统宏观头寸从信号到风控大致走过这条流水线，回答的是「一次交易是如何被规则逐步过滤和约束的」：</p>',13)),(r(),B(A,null,{default:e(()=>[n(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%95%B0%E6%8D%AE%E6%8E%A5%E5%85%A5%20%E5%88%A9%E7%8E%87%20%E6%B1%87%E7%8E%87%20%E5%95%86%E5%93%81%22%5D%20--%3E%20B%5B%22%E4%BF%A1%E5%8F%B7%E8%AE%A1%E7%AE%97%20%E8%B6%8B%E5%8A%BF%20%E5%A5%97%E6%81%AF%20%E4%BB%B7%E5%80%BC%22%5D%0A%20%20B%20--%3E%20C%5B%22%E4%BF%A1%E5%8F%B7%E5%90%88%E6%88%90%E6%89%93%E5%88%86%22%5D%0A%20%20C%20--%3E%20D%7B%22%E6%89%93%E5%88%86%E8%B6%85%E8%BF%87%E9%98%88%E5%80%BC%E5%90%97%22%7D%0A%20%20D%20--%20%22%E5%90%A6%22%20--%3E%20E%5B%22%E7%A9%BA%E4%BB%93%E8%A7%82%E6%9C%9B%22%5D%0A%20%20D%20--%20%22%E6%98%AF%22%20--%3E%20F%5B%22%E6%B3%A2%E5%8A%A8%E7%8E%87%E7%9B%AE%E6%A0%87%E6%8D%A2%E7%AE%97%E4%BB%93%E4%BD%8D%22%5D%0A%20%20F%20--%3E%20G%7B%22%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8E%E9%99%90%E9%A2%9D%E5%A4%9F%E5%90%97%22%7D%0A%20%20G%20--%20%22%E5%90%A6%22%20--%3E%20H%5B%22%E7%BC%A9%E5%87%8F%E5%88%B0%E9%99%90%E9%A2%9D%E5%86%85%22%5D%0A%20%20G%20--%20%22%E6%98%AF%22%20--%3E%20I%5B%22%E4%B8%8B%E5%8D%95%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20I%20--%3E%20J%5B%22%E8%B7%9F%E8%B8%AA%E5%A4%B1%E6%95%88%E6%9D%A1%E4%BB%B6%E5%B9%B6%E6%AD%A2%E6%8D%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"波动瞄准举例：策略目标是年化 \\(10\\%\\) 波动，过去 20 天的日波动是 \\(0.5\\%\\)（年化约 \\(8\\%\\)），那么仓位就按 \\(10/8\\) 加杠杆约 \\(1.25\\) 倍。波动一涨，仓位自动缩——这就是为什么宏观基金在暴跌时常常「越跌越卖」，不是恐慌而是规则。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"政策改变贴现率与风险偏好，资产类别同时重估。宏观赚的是重估的一部分，付的是时机与拥挤（同类 CTA 同向）。反身性：仓位本身影响汇率与利率，大到一定规模就改变对象。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"「反身性」可以把它想象成在浴缸里搅水：水会被你搅动，搅出的波浪又反过来推动你的手。索罗斯用它解释为什么汇率趋势常常自我强化——资金流入推高汇率，汇率走强又吸引更多资金流入，直到某个外生事件打破循环。")],-1)),(r(),B(A,null,{default:e(()=>[n(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Pol%5B%22%E6%94%BF%E7%AD%96%E4%B8%8E%E5%91%A8%E6%9C%9F%22%5D%20--%3E%20XA%5B%22%E8%B7%A8%E8%B5%84%E4%BA%A7%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20Sys%5B%22%E7%B3%BB%E7%BB%9F%20%E8%B6%8B%E5%8A%BF%E5%A5%97%E6%81%AF%22%5D%20--%3E%20XA%0A%20%20Disc%5B%22%E7%9B%B8%E6%9C%BA%20%E5%8F%99%E4%BA%8B%22%5D%20--%3E%20XA%0A%20%20XA%20--%3E%20Risk%5B%22%E4%B9%85%E6%9C%9F%20%E7%BE%8E%E5%85%83%20%E5%95%86%E5%93%81%E5%9B%A0%E5%AD%90%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>新兴市场宏观还有可兑换、资本管制、NDF，见 <a href="/quant/ndf">NDF</a>。本课不写如何交易未公开政策信息。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宏观是跨资产方向与相对价格，风险在杠杆与相关突变。</li><li>系统与相机必须分报；勿用单一故事当持续性证据。</li><li>容量约束是保证金与限额，不是借券。</li><li>出处：趋势与套息见本栏对应课；宏观作为策略族见机构实务分类。</li></ul>',4))])}const q=i(p,[["render",D]]);export{b as __pageData,q as default};
